WITH review_input (
  professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
  attendance_required, grade_received, engagement_level, tags, created_at, import_key, course_ids
) AS (
  VALUES 
    (708::BIGINT, 'Meta con el. Muy amable, calmado, paciente, explica bien, ayuda mucho (si se le pide) durante los lab, extiende fechas, reponde rapido mensajes, si se aprende y examenes cortos pero algo complejos. Las bitacoras y los informes son largos y aburridos, pero pues normal de lab, Apeguese a las rubricas.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Deja trabajos largos', 'Tomaría su clase nuevamente']::TEXT[], '2025-07-16T00:00:00+00:00'::TIMESTAMPTZ, '4df3e303e5aa213ccdf833822e19cbc9fbc4a2e8da9ec8d8522ad43b0e77aabb'::TEXT, ARRAY[3050]::BIGINT[]),
    (708::BIGINT, 'Profe lo juzgué mal al llevar Circuitos con usted en pandemia. En este curso es sin duda de los mejores, sabe de la materia, los labs son fáciles pero se deben trabajar, y los proyectos son la mejor parte, ya que se practica bastante en el lab de Auto.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Brinda apoyo', 'Muchos proyectos grupales']::TEXT[], '2024-12-01T00:00:00+00:00'::TIMESTAMPTZ, 'd700d1dc33cf2661cd48379a455f18d0e85544b5ac2e0dcfa26cca99ec8eaf09'::TEXT, ARRAY[3070]::BIGINT[]),
    (708::BIGINT, 'Él es pura vida. La materia es un poco pesada por la bitácora y reportes, pero eso es por ser un lab. Él intenta ayudarlo a uno lo más posible, da tiempo extra y es superamable. Demasiado recomendado. No participa mucho en clases, pero ayuda siempre si uno se lo pide.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Aspectos de calificación claros', 'Tomaría su clase nuevamente']::TEXT[], '2024-07-24T00:00:00+00:00'::TIMESTAMPTZ, 'fff48daae54b8f6d10e5b9674b16f582e70f157e1135d483136b1edaac5f082f'::TEXT, ARRAY[3050]::BIGINT[]),
    (708::BIGINT, 'Es un gran profesor y persona. El curso se vuelve sencillo gracias a su pasión por la materia y sus explicaciones claras. Es un poco desordenado con el cronograma, pero las evaluaciones son sencillas y dan suficiente tiempo para completarlas.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Clase fácil', 'Asistencia obligatoria', 'Aspectos de calificación claros']::TEXT[], '2023-12-04T00:00:00+00:00'::TIMESTAMPTZ, 'e9e28458839aeb6630b05821f6d9433d6baeff97a177eb65cd806c2f9a1c9687'::TEXT, ARRAY[3070]::BIGINT[]),
    (708::BIGINT, 'De los mejores profes que he tenido, explica bastante bien la materia y ayuda en los laboratorios. A veces las instrucciones no son tan claras, pero se le puede preguntar para aclarar las dudas. El curso se pasa fácil haciendo todos los laboratorios y practicando, se aprende bastante.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2023-06-26T00:00:00+00:00'::TIMESTAMPTZ, '594461c1db17114829fe555ae7fdca763fc7e95f956490e2ec88a71c1eb8b2e4'::TEXT, ARRAY[3070]::BIGINT[]),
    (708::BIGINT, 'El profe es un 100, ayuda un monton y uno aprende mucho en el curso. Se nota que sabe mucho pero a veces es muy charral con las instrucciones, califica suave y si ve que uno le pone, es casi imposible quedarse.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Asistencia obligatoria', 'Aspectos de calificación claros']::TEXT[], '2023-06-15T00:00:00+00:00'::TIMESTAMPTZ, '02bf798a3dfaa2ded8d8f906670d0a20a8e7fcbebedbb410ac40787ecaa3590d'::TEXT, ARRAY[3070]::BIGINT[]),
    (708::BIGINT, 'El profe explica bien la materia, excepto por ocasiones en las que se tarda mucho haciendo algún ejemplo y/o revisando trabajos de cada grupo (incluso con un asistente se tarda mucho). Por lo demás el curso termina siendo sencillo ya que califica bien suave.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Pocos exámenes', 'Aspectos de calificación claros', 'Muchos proyectos grupales']::TEXT[], '2022-11-26T00:00:00+00:00'::TIMESTAMPTZ, '9da1343162cc626de2825e154331d5b0e6935918f91424c0152d7a7518235e83'::TEXT, ARRAY[3070]::BIGINT[]),
    (708::BIGINT, 'Es una teja, brinda muchísima ayuda'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo']::TEXT[], '2022-11-10T00:00:00+00:00'::TIMESTAMPTZ, '40f19fe8a746839ee9612630c81c0b408117f8f8fb875da02cb3dba16709bf80'::TEXT, ARRAY[3070]::BIGINT[]),
    (708::BIGINT, 'Los ejemplos durante las clases presenciales ayudaron mucho al examen aunque el regreso fue un poco lento'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Exámenes retadores']::TEXT[], '2022-10-25T00:00:00+00:00'::TIMESTAMPTZ, '42bf56c4f908221f8ffa2d2d08600072787d0b641dff8abc8bb68a03647f8c7f'::TEXT, ARRAY[3050]::BIGINT[]),
    (708::BIGINT, 'En virtual la materia se hizo un poco más llevadera ya que tenía varios apoyos como sus presentaciones. En el regreso a presencialidad todo eso se derrumbó. Las clases fueron poco claras y se equivocaba mucho haciendo ejercicios. Llegaba muy tarde a clases presenciales.'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Clases largas', 'Exámenes retadores']::TEXT[], '2022-08-14T00:00:00+00:00'::TIMESTAMPTZ, 'bcb321fb71e37befb80af1d8f0e08c4744306024abe77b1d1b6bb208bccf616e'::TEXT, ARRAY[3050]::BIGINT[]),
    (708::BIGINT, 'Se adaptó bastante bien a la presencialidad. Como persona es muy buena gente. Resuelve todas las dudas que uno tenga.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo']::TEXT[], '2022-06-22T00:00:00+00:00'::TIMESTAMPTZ, 'cfe99a9974e2f82a17559edde672970b739b43ec3b8c1992e6ee1ff09d2c3623'::TEXT, ARRAY[3049]::BIGINT[]),
    (708::BIGINT, 'El profe es una teja, muy comprensivo con reclamos y para ayudar a los estudiantes si se lo piden. Hay que ponerle pero el regreso a clases presenciales lo realizo muy bien y las clases virtuales son tediosas pero trata de explicar lo importante'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-05-17T00:00:00+00:00'::TIMESTAMPTZ, 'b1cc4064a4b1d8158625f69c7367fef27329d712ffed797f854a3d683ef7c827'::TEXT, ARRAY[3050]::BIGINT[]),
    (708::BIGINT, 'Llevé este curso por segunda vez y por dicha el profe ha mejorado. Explica bien pero hay que estar atento, como es un curso tan difícil hay que ser muy autodidacta. Hay que estudiar muchísimo para los exámenes (que son los mismos para ambos profes). A pesar de que tiene sus cosas, es la mejor opción'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Brinda apoyo', 'Exámenes retadores']::TEXT[], '2021-11-28T00:00:00+00:00'::TIMESTAMPTZ, '3c7cb0f109f1c2913992f8dfab3dde192651abdc97e584c91386c84f93bd946b'::TEXT, ARRAY[3050]::BIGINT[]),
    (708::BIGINT, 'En general, me dijeron que este semestre fue mucho más dócil. El profe explica bastante claro, aunque a veces comete errores. Sin embargo, el profe si es capaz de aceptar reclamos justificados, e inclusive, da puntos extra si lo considera justo.'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Exámenes retadores']::TEXT[], '2021-11-24T00:00:00+00:00'::TIMESTAMPTZ, '7eb304b8c21daf5d69d4ab1ca7b08c826548405065cc6304a391bed19ef266ca'::TEXT, ARRAY[3049, 3050]::BIGINT[]),
    (708::BIGINT, 'El curso es bien difícil, hay que estudiar todo el tiempo y cumplir con sus tareas por completo, ayúdese con las tutorías. Este profe es su mejor opción de igual forma.'::TEXT, 2.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-11-22T00:00:00+00:00'::TIMESTAMPTZ, 'bb0c14b310d362183db24bf41d76897c49cf718272f61cce9ae17f7fa133a441'::TEXT, ARRAY[3050]::BIGINT[]),
    (708::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2021-08-18T00:00:00+00:00'::TIMESTAMPTZ, 'e9fca0463e12f1daa86a16826475af170b63d412c7a46c874d351d47f69adc8b'::TEXT, ARRAY[3049]::BIGINT[]),
    (708::BIGINT, 'Las clases pueden resultar difíciles de entender, pero ayuda mucho en hora de consulta incluso fuera del horario regular. Se pasa si le dedica bastante tiempo al curso y aprovecha las horas de consulta'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Brinda apoyo']::TEXT[], '2021-07-15T00:00:00+00:00'::TIMESTAMPTZ, 'de7b1bb1db9f6e7bfa3399ca39392611229ea134aa00de12610482444ffb3256'::TEXT, ARRAY[3049]::BIGINT[]),
    (708::BIGINT, 'El profe esta muy dispuesto a ayudar, pero el curso en sí es muy difícil, por eso lo suelen calificar mal, no es culpa de él. Recomendado.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Respetado por los estudiantes', 'Exámenes retadores']::TEXT[], '2021-07-15T00:00:00+00:00'::TIMESTAMPTZ, '64061a803d9f3994d56b18527b12aecbd2aeb0c179d7cb35d5d17d3e402d1fe1'::TEXT, ARRAY[3049]::BIGINT[]),
    (708::BIGINT, 'Prepárese si piensa llevar Circuitos con él, porque el profe es un caso, para entenderle e ir al día con la materia se debe practicar mucho y estar con los libros al lado. Los exámenes son muy rudos y dura bastante tiempo en calificar las pruebas y las tareas.'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Requiere mucha lectura', 'Exámenes retadores']::TEXT[], '2021-07-02T00:00:00+00:00'::TIMESTAMPTZ, 'd8b9f5d122a74de80ff8d199eb4e09383789864294d0e2f231fb5ac939bc8b2b'::TEXT, ARRAY[3049, 3050]::BIGINT[]),
    (708::BIGINT, 'El profe es un caso especial, ya que examenes son muy difíciles y largos para el tiempo que se da, ademas sus clases son regulares, pero si se hacen las guías antes mejoran. Ayuda mucho en consultas y con reclamos. Es aceptable pero si se debe saber que hay que estudiar mucho, la materia lo requiere'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Brinda apoyo', 'Exámenes retadores']::TEXT[], '2021-06-30T00:00:00+00:00'::TIMESTAMPTZ, 'f9456e9d9ce57db9e61175a1cfff2a23a73ab76003891616da749511796f57c5'::TEXT, ARRAY[3049]::BIGINT[]),
    (708::BIGINT, 'Utiliza 3 o 4 plataformas digitales al mismo tiempo'::TEXT, 2.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('55','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Exámenes retadores']::TEXT[], '2021-03-27T00:00:00+00:00'::TIMESTAMPTZ, '35959c7750f588f0c3259b1ab70f67586fb69211c562406cfe45a47a24646067'::TEXT, ARRAY[3050]::BIGINT[]),
    (708::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Requiere mucha lectura', 'Exámenes retadores']::TEXT[], '2021-02-15T00:00:00+00:00'::TIMESTAMPTZ, '7b4aca707afab8f804dac950f03d70d79bdd9f70a16af270594379e75ea9c9a4'::TEXT, ARRAY[3050]::BIGINT[]),
    (708::BIGINT, 'Trata de hacer las clases virtuales cortas y no muy pesadas. Tarda en entregar evaluaciones pero ayuda a quien se lo pide.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Brinda apoyo']::TEXT[], '2021-02-04T00:00:00+00:00'::TIMESTAMPTZ, 'e91ee33817601efb1c720f731953dbcbed8788318433167afb193c4f2d7d7b31'::TEXT, ARRAY[3049]::BIGINT[]),
    (708::BIGINT, 'Tarda mucho en devolver las evaluaciones, en virtual deja guias para desarrollar y en las clases sincrónicas explica como si ya supiera la materia. Muy accesible para resolver dudas o consultas aún fuera del "Horario Normal"'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Requiere mucha lectura', 'Exámenes retadores']::TEXT[], '2021-02-04T00:00:00+00:00'::TIMESTAMPTZ, '19a16624f83e4bb210db121cbb39a7d6cc450402371e13e1fbe926a30d5f2d45'::TEXT, ARRAY[3050]::BIGINT[]),
    (708::BIGINT, 'No lo haga. Mejor no lo matricule. O sepa que le toca sol@ con el libro y youtube. Y suerte en los examenes. Que, por cierto, los entrega mes y medio despues. En presencial hizo quices sorpresa. Virtual las clases son una perdida de tiempo. Ademas explica como para alguien que ya lo sabe todo.'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Exámenes retadores']::TEXT[], '2020-08-25T00:00:00+00:00'::TIMESTAMPTZ, 'dc3297817b90d68da0ba5649391ad37345ae92f5abbf1993d9cf6783add56d36'::TEXT, ARRAY[3050]::BIGINT[]),
    (708::BIGINT, 'Realmente lleve el curso virtual y por esta razón siento que la dificultad aumento, pero aun así el profesor dura una eternidad para revisar los exámenes y trabajos es decir hasta el ultimo examen uno se da cuenta si tiene oportunidad de pasar o no. Escribe la A como un delta.'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Requiere mucha lectura']::TEXT[], '2020-08-10T00:00:00+00:00'::TIMESTAMPTZ, 'dd5d7062c61923335ec0a9e1ef0b7d3c22557793a94e4da51a9d6064be8f4cda'::TEXT, ARRAY[3049]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
